<template><div class="p-2 app-container"><el-card shadow="never"><template #header><div class="header"><div><h3>充值订单</h3><p>查看用户充值金额、到账余额和支付状态。</p></div><el-button icon="Refresh" @click="load">刷新</el-button></div></template><el-table v-loading="loading" :data="rows" border><el-table-column prop="order_no" label="订单号" min-width="220"/><el-table-column prop="email" label="用户邮箱" min-width="180"/><el-table-column prop="package_name" label="套餐"/><el-table-column prop="amount" label="支付金额" width="100"/><el-table-column prop="credits" label="到账余额" width="100"/><el-table-column label="状态" width="100"><template #default="scope"><el-tag :type="scope.row.status==='PAID'?'success':'warning'">{{scope.row.status==='PAID'?'已支付':'待支付'}}</el-tag></template></el-table-column><el-table-column prop="gateway_order_no" label="支付流水号" min-width="180"/><el-table-column prop="paid_time" label="支付时间" min-width="170"/><el-table-column prop="create_time" label="创建时间" min-width="170"/></el-table></el-card></div></template>
<script setup lang="ts">import {listOrders} from '@/api/aigc/billing';const rows=ref<any[]>([]);const loading=ref(false);async function load(){loading.value=true;try{const r:any=await listOrders();rows.value=r.data||r||[]}finally{loading.value=false}}onMounted(load);</script>
<style scoped>.header{display:flex;justify-content:space-between;align-items:center}h3{margin:0 0 6px}p{margin:0;color:#8492a6;font-size:13px}</style>
